//! Versioned wrappers for the unified TrUAPI contract.
//!
//! A versioned wrapper is a SCALE enum whose variants (`V1`, `V2`, ...) are
//! successive retained versions of one logical message, newest last. Retiring
//! a prefix does not renumber the remaining wire discriminants. A server
//! normalizes incoming values to [`Versioned::Latest`] with [`IntoLatest`],
//! handles them in latest terms, then maps results back to the caller's version
//! with [`FromLatest`]. The wrappers themselves are generated by `versioned_type!`,
//! one per leg of a method's exchange (its request, its response, a
//! subscription's item, ...): which leg a frame carries is the wire's own
//! `message_type` byte, addressed alongside `(trait, method)` rather than
//! encoded inside any of these payloads.

/// A versioned message envelope.
///
/// The first encoded byte is `version() - 1`. Retained versions are contiguous
/// through [`LATEST`](Self::LATEST), but an older prefix may have been retired.
/// The dispatcher rejects newer versions; decoding rejects retired variants.
pub trait Versioned: Sized {
	/// The newest version's payload. Handlers operate exclusively on this.
	type Latest;

	/// Version number of the newest variant.
	const LATEST: u8;

	/// Version number of the variant currently held.
	fn version(&self) -> u8;
}

/// Upgrade a received envelope to its latest payload. Total by construction.
pub trait IntoLatest: Versioned {
	/// Convert whatever version is held into the latest payload.
	fn into_latest(self) -> Self::Latest;
}

/// Downgrade a latest payload into the variant a peer at `target` understands.
pub trait FromLatest: Versioned {
	/// Build the envelope for protocol version `target` (highest variant ≤ target).
	fn from_latest(latest: Self::Latest, target: u8) -> Self;
}

